  "witnessCode": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('normalizeUrl removes directory index', () => {
  const url = 'http://example.com/foo/bar/index.html';
  const opts = { removeDirectoryIndex: true };
  const result = normalizeUrl(url, opts);
  assert.strictEqual(result, 'http://example.com/foo/bar');
});"
